function _validate(bucket, key, obj) {
    // Check if required bucket
    $allowed_buckets = $modconf.allowed_buckets
    if ($allowed_buckets and not $allowed_buckets.has($bucket)) {
        $lib.raise('INVALID_BUCKET', `Bucket not allowed: {$bucket}`)
    }

    // Check key prefix
    $required_prefix = $modconf.required_prefix
    if ($required_prefix and not $key.startswith($required_prefix)) {
        $lib.raise('INVALID_PREFIX', `Key must start with prefix: {$required_prefix}`)
    }

    // Check payload size
    $max_bytes = $modconf.max_bytes
    $serialized = $lib.json.save($obj)
    if ($serialized.size() > $max_bytes) {
        $lib.raise('PAYLOAD_EXCEEDS_MAX_BYTES', `Payload exceeds max_bytes {$max_bytes}`)
    }
}

